// ============================================================
// Electron main process for the Huobao Drama AI desktop app.
//
// Architecture: the Next.js app runs as a real HTTP server
// (.next/standalone/server.js, spawned with Electron's own Node via
// ELECTRON_RUN_AS_NODE) against a local SQLite database stored in the
// OS userData directory. The BrowserWindow loads the server URL, so
// every existing API route / auth / AI integration works unchanged.
//
// First run: create the SQLite schema from electron/sqlite-init.sql
// (generated by scripts/prepare-desktop.js) and seed an admin user.
// Then sign in automatically via the NextAuth credentials flow and
// inject the session cookie into the window session.
// ============================================================

const { app, BrowserWindow, dialog, shell } = require('electron')
const { spawn } = require('child_process')
const path = require('path')
const fs = require('fs')
const crypto = require('crypto')
const net = require('net')

// ---------- Paths ----------

const projectRoot = path.join(__dirname, '..')
const standaloneDir = app.isPackaged
  ? path.join(process.resourcesPath, 'standalone')
  : path.join(projectRoot, '.next', 'standalone')
const serverJs = path.join(standaloneDir, 'server.js')
const initSqlPath = path.join(__dirname, 'sqlite-init.sql')

const userDataDir = app.getPath('userData')
const dbPath = path.join(userDataDir, 'huobao.db')
const configPath = path.join(userDataDir, 'desktop-config.json')
const aiProvidersPath = path.join(userDataDir, 'ai-providers.json')
const serverLogPath = path.join(userDataDir, 'server.log')

// ---------- Config (persisted secret + admin credentials) ----------

// Defaults match scripts/build.js so Vercel and desktop stay consistent.
const DEFAULT_ADMIN_EMAIL = process.env.ADMIN_EMAIL || 'admin@huobao.com'
const DEFAULT_ADMIN_PASSWORD = process.env.ADMIN_PASSWORD || 'admin123'

function loadConfig() {
  let saved = {}
  try {
    saved = JSON.parse(fs.readFileSync(configPath, 'utf8'))
  } catch {
    // first run
  }
  const config = {
    nextAuthSecret: saved.nextAuthSecret || crypto.randomBytes(32).toString('base64'),
    adminEmail: saved.adminEmail || DEFAULT_ADMIN_EMAIL,
    adminPassword: saved.adminPassword || DEFAULT_ADMIN_PASSWORD,
  }
  try {
    fs.writeFileSync(configPath, JSON.stringify(config, null, 2))
  } catch (err) {
    console.error('[desktop] Failed to persist config:', err.message)
  }
  return config
}

// Desktop AI key config — a dedicated, never-rewritten JSON file so the
// user can fill in provider keys without env vars or the settings UI.
// The server reads it via HUOBAO_DESKTOP_CONFIG (src/lib/ai-config.ts).
function ensureAiProvidersTemplate() {
  if (fs.existsSync(aiProvidersPath)) return
  const template = {
    _说明: '桌面版 AI 密钥配置文件。按类目填写 provider 和 apiKey 即可，无需环境变量。留空或删除的类目会回退到应用内「设置」页配置 → 内置免费渠道。',
    _生效顺序: '本文件 > 应用内设置页 > 环境变量 > 内置免费渠道(z-ai-sdk)',
    image: {
      _可选provider: 'z-ai-sdk | openai | chatfire | gemini | minimax | volcengine | ali | agnes | custom',
      provider: '',
      apiKey: '',
      model: '',
      baseUrl: '',
    },
    llm: {
      _可选provider: 'z-ai-sdk | nvidia | openai | siliconflow | deepseek | sensenova | openrouter | mimo | agnes | custom',
      provider: '',
      apiKey: '',
      model: '',
      baseUrl: '',
    },
    video: {
      _可选provider: 'z-ai-sdk | minimax | volcengine | vidu | ali | scnet | agnes | custom',
      provider: '',
      apiKey: '',
      model: '',
      baseUrl: '',
    },
    tts: {
      _可选provider: 'z-ai-sdk | minimax | openai | chatfire | ali | fish-audio | mimo | custom',
      provider: '',
      apiKey: '',
      model: '',
      baseUrl: '',
    },
  }
  try {
    fs.writeFileSync(aiProvidersPath, JSON.stringify(template, null, 2))
    console.log(`[desktop] AI key config template created: ${aiProvidersPath}`)
  } catch (err) {
    console.error('[desktop] Failed to create AI key config template:', err.message)
  }
}

// Prisma resolves `file:` URLs — absolute path with forward slashes works on Windows too.
const databaseUrl = `file:${dbPath.replace(/\\/g, '/')}`

// ---------- First-run database init + admin seed ----------

// electron-builder hard-excludes "node_modules" from extraResources, so the
// packaged server deps ship as "runtime-modules"; junction-link them back
// before spawning the server (no admin rights needed for junctions).
function ensureServerNodeModules() {
  const nodeModules = path.join(standaloneDir, 'node_modules')
  const runtimeModules = path.join(standaloneDir, 'runtime-modules')
  if (fs.existsSync(runtimeModules) && !fs.existsSync(nodeModules)) {
    fs.symlinkSync(runtimeModules, nodeModules, 'junction')
    console.log('[desktop] Linked runtime-modules → node_modules')
  }
}

async function ensureDatabase() {
  // Load the generated Prisma client from the standalone bundle — electron-builder
  // does not collect the virtual ".prisma/client" package into app.asar, but the
  // standalone copy (copied by scripts/prepare-desktop.js) is always present.
  const prismaClientMod = require(
    path.join(standaloneDir, 'node_modules', '.prisma', 'client')
  )
  const PrismaClient = prismaClientMod.PrismaClient || prismaClientMod.default?.PrismaClient
  const bcrypt = require('bcryptjs')
  const db = new PrismaClient({ datasources: { db: { url: databaseUrl } } })

  try {
    const tables = await db.$queryRawUnsafe(
      `SELECT name FROM sqlite_master WHERE type='table' AND name='User'`
    )
    if (!tables || tables.length === 0) {
      console.log('[desktop] Empty database — applying schema from sqlite-init.sql...')
      const sql = fs.readFileSync(initSqlPath, 'utf8')
      const statements = sql
        .split(';')
        .map((s) => s.trim())
        .filter((s) => s.length > 0)
      for (const stmt of statements) {
        await db.$executeRawUnsafe(stmt)
      }
      console.log(`[desktop] Schema applied (${statements.length} statements)`)
    }

    // Seed admin user (only if missing — never overwrite existing credentials)
    const config = loadConfig()
    const existing = await db.user.findUnique({ where: { email: config.adminEmail } })
    if (!existing) {
      await db.user.create({
        data: {
          email: config.adminEmail,
          name: '管理员',
          password: bcrypt.hashSync(config.adminPassword, 10),
          role: 'admin',
        },
      })
      console.log(`[desktop] Admin user created: ${config.adminEmail}`)
    }
  } finally {
    await db.$disconnect().catch(() => {})
  }
}

// ---------- Next.js server management ----------

let serverProcess = null

function startServer(config, port) {
  // Child env: force SQLite + local auth, strip any Postgres/Vercel leftovers.
  const childEnv = { ...process.env }
  for (const key of Object.keys(childEnv)) {
    if (/^(huobao_)?POSTGRES_/i.test(key) || key === 'DIRECT_URL' || key === 'VERCEL') {
      delete childEnv[key]
    }
  }
  childEnv.DATABASE_URL = databaseUrl
  childEnv.NEXTAUTH_SECRET = config.nextAuthSecret
  childEnv.NEXTAUTH_URL = `http://127.0.0.1:${port}`
  childEnv.AUTH_TRUST_HOST = 'true'
  childEnv.NODE_ENV = 'production'
  childEnv.HUOBAO_DESKTOP = '1'
  childEnv.HUOBAO_DESKTOP_CONFIG = aiProvidersPath
  childEnv.PORT = String(port)
  childEnv.HOSTNAME = '127.0.0.1'
  childEnv.ELECTRON_RUN_AS_NODE = '1'

  const logStream = fs.createWriteStream(serverLogPath, { flags: 'a' })
  logStream.write(`\n===== desktop launch ${new Date().toISOString()} (port ${port}) =====\n`)

  serverProcess = spawn(process.execPath, [serverJs], {
    cwd: standaloneDir,
    env: childEnv,
    stdio: ['ignore', 'pipe', 'pipe'],
  })
  serverProcess.stdout.pipe(logStream)
  serverProcess.stderr.pipe(logStream)
  serverProcess.on('exit', (code) => {
    console.log(`[desktop] Next server exited with code ${code}`)
    serverProcess = null
  })
}

function stopServer() {
  if (serverProcess) {
    try {
      serverProcess.kill()
    } catch {
      // already gone
    }
    serverProcess = null
  }
}

function getFreePort() {
  return new Promise((resolve, reject) => {
    const srv = net.createServer()
    srv.listen(0, '127.0.0.1', () => {
      const { port } = srv.address()
      srv.close(() => resolve(port))
    })
    srv.on('error', reject)
  })
}

async function waitForServer(baseUrl, timeoutMs = 90000) {
  const deadline = Date.now() + timeoutMs
  while (Date.now() < deadline) {
    if (!serverProcess) throw new Error('Next server process died during startup')
    try {
      const res = await fetch(`${baseUrl}/api/auth/csrf`, { signal: AbortSignal.timeout(3000) })
      if (res.ok) return
    } catch {
      // not ready yet
    }
    await new Promise((r) => setTimeout(r, 500))
  }
  throw new Error(`Server did not become ready within ${timeoutMs / 1000}s`)
}

// ---------- Auto sign-in (NextAuth credentials flow) ----------

function getSetCookie(res, name) {
  const cookies = res.headers.getSetCookie ? res.headers.getSetCookie() : []
  for (const c of cookies) {
    if (c.startsWith(`${name}=`)) return c
  }
  return null
}

async function autoSignIn(baseUrl, config) {
  // CSRF token + its cookie
  const csrfRes = await fetch(`${baseUrl}/api/auth/csrf`)
  if (!csrfRes.ok) throw new Error(`csrf endpoint returned ${csrfRes.status}`)
  const { csrfToken } = await csrfRes.json()
  const csrfCookie = getSetCookie(csrfRes, 'next-auth.csrf-token')

  // Credentials callback — capture the session cookie from the redirect response
  const body = new URLSearchParams({ csrfToken, email: config.adminEmail, password: config.adminPassword, json: 'true' })
  const res = await fetch(`${baseUrl}/api/auth/callback/credentials`, {
    method: 'POST',
    redirect: 'manual',
    headers: {
      'Content-Type': 'application/x-www-form-urlencoded',
      ...(csrfCookie ? { Cookie: csrfCookie } : {}),
    },
    body: body.toString(),
  })
  const sessionCookie = getSetCookie(res, 'next-auth.session-token')
  if (!sessionCookie) throw new Error(`no session cookie (callback returned ${res.status})`)

  const value = sessionCookie.split(';')[0].split('=').slice(1).join('=')
  await win.webContents.session.cookies.set({
    url: baseUrl,
    name: 'next-auth.session-token',
    value,
    httpOnly: true,
    sameSite: 'lax',
    expirationDate: Math.floor(Date.now() / 1000) + 60 * 60 * 24 * 30,
  })
  console.log('[desktop] Auto sign-in OK')
}

// ---------- Window ----------

let win = null

const SPLASH_HTML = `data:text/html;charset=utf-8,${encodeURIComponent(`
<!doctype html><html><head><meta charset="utf-8"><style>
  body{margin:0;height:100vh;display:flex;flex-direction:column;align-items:center;justify-content:center;
       background:#0a0a0a;color:#fafafa;font-family:system-ui,sans-serif}
  h1{font-size:22px;font-weight:600;margin-bottom:8px}
  p{color:#a1a1aa;font-size:14px}
  .bar{width:200px;height:3px;background:#27272a;border-radius:2px;overflow:hidden;margin-top:24px}
  .bar::after{content:'';display:block;width:40%;height:100%;background:#a1a1aa;border-radius:2px;
       animation:slide 1.2s ease-in-out infinite}
  @keyframes slide{0%{transform:translateX(-100%)}100%{transform:translateX(350%)}}
</style></head><body>
  <h1>火爆短剧 AI</h1><p>正在启动本地服务…</p><div class="bar"></div>
</body></html>`)}`

function createWindow(baseUrl) {
  win = new BrowserWindow({
    width: 1440,
    height: 900,
    minWidth: 1024,
    minHeight: 700,
    show: false,
    autoHideMenuBar: true,
    title: '火爆短剧 AI',
    webPreferences: {
      contextIsolation: true,
      nodeIntegration: false,
    },
  })
  win.once('ready-to-show', () => win.show())
  win.webContents.setWindowOpenHandler(({ url }) => {
    if (url.startsWith(baseUrl)) return { action: 'allow' }
    shell.openExternal(url)
    return { action: 'deny' }
  })
  win.loadURL(SPLASH_HTML)
  return win
}

async function bootstrap() {
  const config = loadConfig()
  const port = await getFreePort()
  const baseUrl = `http://127.0.0.1:${port}`

  createWindow(baseUrl)
  ensureServerNodeModules()
  ensureAiProvidersTemplate()
  console.log(`[desktop] AI key config: ${aiProvidersPath}`)
  await ensureDatabase()
  startServer(config, port)
  await waitForServer(baseUrl)

  try {
    await autoSignIn(baseUrl, config)
  } catch (err) {
    console.warn('[desktop] Auto sign-in failed, falling back to the login page:', err.message)
  }
  await win.loadURL(baseUrl)
}

// ---------- App lifecycle ----------

if (!app.requestSingleInstanceLock()) {
  app.quit()
} else {
  app.on('second-instance', () => {
    if (win) {
      if (win.isMinimized()) win.restore()
      win.focus()
    }
  })

  app.whenReady().then(async () => {
    if (!fs.existsSync(serverJs)) {
      dialog.showErrorBox(
        '缺少构建产物',
        '未找到 .next/standalone/server.js。\n请先在项目目录执行: bun run desktop:prepare'
      )
      app.quit()
      return
    }
    try {
      await bootstrap()
    } catch (err) {
      console.error('[desktop] Bootstrap failed:', err)
      dialog.showErrorBox('启动失败', String(err.message || err))
      app.quit()
    }
  })

  app.on('before-quit', stopServer)
  app.on('window-all-closed', () => {
    stopServer()
    app.quit()
  })
}
